//! Physical SimSat radiance -> upstream 33-term FP32 glossy SHE fit.
//!
//! The environment source is a sealed positive log-SH3 sky-*radiance* row
//! generated by the SimSat project's Hillaire atmosphere implementation. It is
//! intentionally distinct from the diffuse-irradiance row used by cloud fill.

use crate::{
    lighting::sh3_basis,
    she::{SheSpecularCoefficients, construct_sh_vector_a, reconstruct_specular},
};
use bevy::math::Vec3;
use sha2::{Digest, Sha256};
use std::f32::consts::PI;

pub const SIMSAT_RADIANCE_ASSET: &[u8; 204] =
    include_bytes!("../assets/t300-sky-radiance-log-sh3.f32le");
pub const SIMSAT_RADIANCE_SHA256: &str =
    "12838043df7c505720b43addde2118aeac6aa550ace0cfb12e03afad09ced2d5";
pub const SIMSAT_RADIANCE_SOURCE_SHA256: &str =
    "6e9373ae7f8277cd62e9391c44bb1fc9cb8b3d72b92d61a3ecb25056ffd5d814";
pub const SIMSAT_BUNDLE_PATCH_SHA256: &str =
    "1b59329f76f642daf3e6a97e7efe250d8098d904b17d610696fa5e6764e6acac";
pub const SPECULAR_TRAIN_RESOLUTION: u32 = 48;
pub const SPECULAR_TRAIN_GGX_SAMPLES: u32 = 256;
pub const SPECULAR_HELD_RESOLUTION: u32 = 13;
pub const SPECULAR_HELD_GGX_SAMPLES: u32 = 384;
pub const SPECULAR_ALPHA_LEVELS: [f32; 4] = [0.2, 0.466_666_67, 0.733_333_35, 1.0];

#[derive(Clone, Copy, Debug)]
pub struct SimSatSkyRadiance {
    pub log_coefficients: [[f32; 3]; 16],
    pub amplitude: [f32; 3],
}

impl SimSatSkyRadiance {
    pub fn sealed_t300() -> Result<Self, String> {
        let hash = format!("{:x}", Sha256::digest(SIMSAT_RADIANCE_ASSET));
        if hash != SIMSAT_RADIANCE_SHA256 {
            return Err("sealed SimSat sky-radiance asset hash changed".to_owned());
        }
        let mut words = SIMSAT_RADIANCE_ASSET
            .chunks_exact(4)
            .map(|bytes| f32::from_le_bytes(bytes.try_into().expect("four-byte asset word")));
        let log_coefficients = std::array::from_fn(|_| {
            std::array::from_fn(|_| words.next().expect("16 RGB coefficients"))
        });
        let amplitude = std::array::from_fn(|_| words.next().expect("RGB amplitude"));
        if words.next().is_some()
            || !log_coefficients
                .iter()
                .flatten()
                .all(|value| value.is_finite())
            || !amplitude
                .iter()
                .all(|value| value.is_finite() && *value > 0.0)
        {
            return Err("sealed SimSat sky-radiance row is invalid".to_owned());
        }
        Ok(Self {
            log_coefficients,
            amplitude,
        })
    }

    pub fn evaluate(self, direction: Vec3) -> Vec3 {
        let direction = direction.normalize();
        let basis = sh3_basis(direction.to_array().map(f64::from));
        Vec3::from_array(std::array::from_fn(|channel| {
            let log_value = self
                .log_coefficients
                .iter()
                .zip(basis)
                .map(|(coefficient, weight)| coefficient[channel] * weight as f32)
                .sum::<f32>()
                .clamp(-80.0, 80.0);
            self.amplitude[channel] * log_value.exp()
        }))
    }
}

#[derive(Clone, Copy, Debug)]
pub struct GlossyErrorMetrics {
    pub compared_rgb_words: usize,
    pub max_absolute_radiance: f32,
    pub rms_absolute_radiance: f32,
    pub max_relative: f32,
    pub rms_relative: f32,
    pub max_luminance_absolute: f32,
    pub rms_luminance_absolute: f32,
    pub rms_luminance_relative: f32,
    pub reference_rms_radiance: f32,
    pub reference_rms_luminance: f32,
    pub normalized_rms_absolute_radiance: f32,
    pub normalized_rms_luminance_absolute: f32,
}

#[derive(Clone, Debug)]
pub struct T300GlossyFit {
    pub coefficients: SheSpecularCoefficients,
    pub coefficients_sha256: String,
    pub training_cases: usize,
    pub ridge: f64,
    pub held: GlossyErrorMetrics,
}

pub fn fit_t300_glossy_she() -> Result<T300GlossyFit, String> {
    let environment = SimSatSkyRadiance::sealed_t300()?;
    let mut normal_matrix = [[0.0_f64; 33]; 33];
    let mut rhs = [[0.0_f64; 3]; 33];
    let mut training_cases = 0usize;
    for normal_index in 0..SPECULAR_TRAIN_RESOLUTION {
        let normal = fibonacci_sphere(normal_index, SPECULAR_TRAIN_RESOLUTION);
        for view_index in 0..SPECULAR_TRAIN_RESOLUTION {
            let view = fibonacci_sphere(view_index, SPECULAR_TRAIN_RESOLUTION);
            if normal.dot(view) <= 0.035 {
                continue;
            }
            for alpha in SPECULAR_ALPHA_LEVELS {
                let target = prefilter_environment_ggx(
                    environment,
                    normal,
                    view,
                    alpha,
                    SPECULAR_TRAIN_GGX_SAMPLES,
                );
                if !target.is_finite() || target.min_element() <= 0.0 {
                    continue;
                }
                let vector = construct_sh_vector_a(normal, view, alpha)?;
                let log_target = target.ln();
                for row in 0..33 {
                    let a_row = f64::from(vector[row]);
                    for column in 0..33 {
                        normal_matrix[row][column] += a_row * f64::from(vector[column]);
                    }
                    for channel in 0..3 {
                        rhs[row][channel] += a_row * f64::from(log_target[channel]);
                    }
                }
                training_cases += 1;
            }
        }
    }
    if training_cases < 512 {
        return Err("insufficient valid physical glossy fit cases".to_owned());
    }
    let trace = (0..33)
        .map(|index| normal_matrix[index][index])
        .sum::<f64>();
    let ridge = trace / 33.0 * 1.0e-7;
    for (index, row) in normal_matrix.iter_mut().enumerate() {
        row[index] += ridge;
    }
    let solved = solve_spd(normal_matrix, rhs)?;
    let coefficients = SheSpecularCoefficients(std::array::from_fn(|index| {
        Vec3::new(
            solved[index][0] as f32,
            solved[index][1] as f32,
            solved[index][2] as f32,
        )
    }));
    if !coefficients
        .0
        .iter()
        .all(|coefficient| coefficient.is_finite())
    {
        return Err("glossy SHE solution is non-finite".to_owned());
    }
    let coefficients_sha256 = specular_coefficients_sha256(&coefficients);
    let held = glossy_held_error(environment, &coefficients)?;
    Ok(T300GlossyFit {
        coefficients,
        coefficients_sha256,
        training_cases,
        ridge,
        held,
    })
}

pub fn prefilter_environment_ggx(
    environment: SimSatSkyRadiance,
    normal: Vec3,
    view: Vec3,
    alpha: f32,
    samples: u32,
) -> Vec3 {
    prefilter_radiance_ggx(
        &|direction| {
            // The sealed SimSat row is fitted from upper-sky samples. Below
            // the physical horizon is not sky radiance and must not use the
            // positive log-SH extrapolation; terrain/ground radiance is a
            // separate source.
            if direction.z > 0.0 {
                environment.evaluate(direction)
            } else {
                Vec3::ZERO
            }
        },
        normal,
        view,
        alpha,
        samples,
    )
}

/// Integrate an arbitrary full-sphere radiance source with the exact GGX
/// source order used by the pinned upstream collector. This is exposed for
/// operator/source-isolation controls; production callers remain responsible
/// for provenance and for distinguishing display radiance from science data.
pub fn prefilter_radiance_ggx<R>(
    radiance: &R,
    normal: Vec3,
    view: Vec3,
    alpha: f32,
    samples: u32,
) -> Vec3
where
    R: Fn(Vec3) -> Vec3,
{
    let ndotv = normal.dot(view);
    if ndotv <= 0.0 || samples == 0 {
        return Vec3::ZERO;
    }
    let mut accumulator = Vec3::ZERO;
    for index in 0..samples {
        let xi = Vec2Like(index as f32 / samples as f32, radical_inverse_vdc(index));
        let half = importance_sample_ggx_alpha(xi, normal, alpha);
        let vdoth = view.dot(half);
        if vdoth <= 0.0 {
            continue;
        }
        let light = 2.0 * vdoth * half - view;
        let ndotl = normal.dot(light);
        if ndotl <= 0.0 {
            continue;
        }
        let ndoth = normal.dot(half);
        let geometry = (2.0 * ndoth * ndotv / vdoth)
            .min(2.0 * ndoth * ndotl / vdoth)
            .min(1.0);
        let weight = geometry * vdoth / (ndotv * ndoth);
        accumulator += radiance(light) * weight;
    }
    accumulator / samples as f32
}

#[derive(Clone, Copy)]
struct Vec2Like(f32, f32);

fn importance_sample_ggx_alpha(xi: Vec2Like, normal: Vec3, alpha: f32) -> Vec3 {
    let phi = 2.0 * PI * xi.0;
    let cosine = ((1.0 - xi.1) / (1.0 + (alpha * alpha - 1.0) * xi.1))
        .sqrt()
        .min(1.0);
    let sine = (1.0 - cosine * cosine).max(0.0).sqrt();
    let local = Vec3::new(phi.cos() * sine, phi.sin() * sine, cosine);
    let up = if normal.z.abs() < 0.999 {
        Vec3::Z
    } else {
        Vec3::X
    };
    let tangent = up.cross(normal).normalize();
    let bitangent = normal.cross(tangent);
    (tangent * local.x + bitangent * local.y + normal * local.z).normalize()
}

fn radical_inverse_vdc(mut bits: u32) -> f32 {
    bits = bits.rotate_right(16);
    bits = ((bits & 0x5555_5555) << 1) | ((bits & 0xaaaa_aaaa) >> 1);
    bits = ((bits & 0x3333_3333) << 2) | ((bits & 0xcccc_cccc) >> 2);
    bits = ((bits & 0x0f0f_0f0f) << 4) | ((bits & 0xf0f0_f0f0) >> 4);
    bits = ((bits & 0x00ff_00ff) << 8) | ((bits & 0xff00_ff00) >> 8);
    bits as f32 * 2.328_306_4e-10
}

fn fibonacci_sphere(index: u32, count: u32) -> Vec3 {
    let phi = PI * (3.0 - 5.0_f32.sqrt());
    let y = 1.0 - 2.0 * index as f32 / (count - 1) as f32;
    let radius = (1.0 - y * y).max(0.0).sqrt();
    let theta = phi * index as f32;
    Vec3::new(radius * theta.cos(), y, radius * theta.sin())
}

#[allow(clippy::needless_range_loop)] // fixed source-order Cholesky transcription
fn solve_spd(matrix: [[f64; 33]; 33], mut rhs: [[f64; 3]; 33]) -> Result<[[f64; 3]; 33], String> {
    let mut lower = [[0.0_f64; 33]; 33];
    for row in 0..33 {
        for column in 0..=row {
            let mut sum = matrix[row][column];
            for k in 0..column {
                sum -= lower[row][k] * lower[column][k];
            }
            if row == column {
                if !sum.is_finite() || sum <= 1.0e-14 {
                    return Err(format!("glossy SHE Cholesky refused row {row}: {sum:e}"));
                }
                lower[row][column] = sum.sqrt();
            } else {
                lower[row][column] = sum / lower[column][column];
            }
        }
    }
    for row in 0..33 {
        for channel in 0..3 {
            let subtract = (0..row)
                .map(|column| lower[row][column] * rhs[column][channel])
                .sum::<f64>();
            rhs[row][channel] = (rhs[row][channel] - subtract) / lower[row][row];
        }
    }
    for row in (0..33).rev() {
        for channel in 0..3 {
            let subtract = (row + 1..33)
                .map(|column| lower[column][row] * rhs[column][channel])
                .sum::<f64>();
            rhs[row][channel] = (rhs[row][channel] - subtract) / lower[row][row];
        }
    }
    Ok(rhs)
}

fn glossy_held_error(
    environment: SimSatSkyRadiance,
    coefficients: &SheSpecularCoefficients,
) -> Result<GlossyErrorMetrics, String> {
    glossy_error_for_coefficients(
        environment,
        coefficients,
        SPECULAR_HELD_RESOLUTION,
        SPECULAR_HELD_GGX_SAMPLES,
        [0.22_f32, 0.41, 0.68, 0.95],
    )
}

pub fn glossy_error_for_coefficients(
    environment: SimSatSkyRadiance,
    coefficients: &SheSpecularCoefficients,
    resolution: u32,
    ggx_samples: u32,
    alpha_levels: [f32; 4],
) -> Result<GlossyErrorMetrics, String> {
    glossy_error_for_radiance(
        &|direction| {
            if direction.z > 0.0 {
                environment.evaluate(direction)
            } else {
                Vec3::ZERO
            }
        },
        coefficients,
        resolution,
        ggx_samples,
        alpha_levels,
    )
}

/// Evaluate held N/V/roughness cases against an arbitrary radiance callback.
/// The error definition and reconstruction are identical to the production
/// admission gate; only the environment source is substituted.
pub fn glossy_error_for_radiance<R>(
    radiance: &R,
    coefficients: &SheSpecularCoefficients,
    resolution: u32,
    ggx_samples: u32,
    alpha_levels: [f32; 4],
) -> Result<GlossyErrorMetrics, String>
where
    R: Fn(Vec3) -> Vec3,
{
    if resolution < 3 || ggx_samples == 0 {
        return Err("glossy held configuration is empty".to_owned());
    }
    let mut max_absolute = 0.0_f32;
    let mut sum_absolute_squared = 0.0_f64;
    let mut max_relative = 0.0_f32;
    let mut sum_relative_squared = 0.0_f64;
    let mut max_luminance_absolute = 0.0_f32;
    let mut sum_luminance_absolute_squared = 0.0_f64;
    let mut sum_luminance_relative_squared = 0.0_f64;
    let mut sum_reference_squared = 0.0_f64;
    let mut sum_luminance_reference_squared = 0.0_f64;
    let mut compared_words = 0usize;
    let mut compared_cases = 0usize;
    for normal_index in 0..resolution {
        let normal = fibonacci_sphere((normal_index * 7 + 3) % resolution, resolution);
        for view_index in 0..resolution {
            let view = fibonacci_sphere((view_index * 5 + 2) % resolution, resolution);
            if normal.dot(view) <= 0.08 {
                continue;
            }
            for alpha in alpha_levels {
                let reference = prefilter_radiance_ggx(radiance, normal, view, alpha, ggx_samples);
                if reference.min_element() <= 0.0 {
                    continue;
                }
                let observed = reconstruct_specular(normal, view, alpha.sqrt(), coefficients)?;
                let error = (observed - reference).abs();
                let relative = error / reference;
                max_absolute = max_absolute.max(error.max_element());
                max_relative = max_relative.max(relative.max_element());
                sum_absolute_squared += error
                    .to_array()
                    .into_iter()
                    .map(|value| f64::from(value * value))
                    .sum::<f64>();
                sum_relative_squared += relative
                    .to_array()
                    .into_iter()
                    .map(|value| f64::from(value * value))
                    .sum::<f64>();
                sum_reference_squared += reference
                    .to_array()
                    .into_iter()
                    .map(|value| f64::from(value * value))
                    .sum::<f64>();
                let luminance_reference = reference.dot(Vec3::new(0.2126, 0.7152, 0.0722));
                let luminance_observed = observed.dot(Vec3::new(0.2126, 0.7152, 0.0722));
                let luminance_error = (luminance_observed - luminance_reference).abs();
                max_luminance_absolute = max_luminance_absolute.max(luminance_error);
                sum_luminance_absolute_squared += f64::from(luminance_error * luminance_error);
                sum_luminance_relative_squared +=
                    f64::from((luminance_error / luminance_reference).powi(2));
                sum_luminance_reference_squared +=
                    f64::from(luminance_reference * luminance_reference);
                compared_words += 3;
                compared_cases += 1;
            }
        }
    }
    if compared_cases == 0 {
        return Err("no glossy held cases were compared".to_owned());
    }
    let rms_absolute_radiance = (sum_absolute_squared / compared_words as f64).sqrt() as f32;
    let rms_luminance_absolute =
        (sum_luminance_absolute_squared / compared_cases as f64).sqrt() as f32;
    let reference_rms_radiance = (sum_reference_squared / compared_words as f64).sqrt() as f32;
    let reference_rms_luminance =
        (sum_luminance_reference_squared / compared_cases as f64).sqrt() as f32;
    Ok(GlossyErrorMetrics {
        compared_rgb_words: compared_words,
        max_absolute_radiance: max_absolute,
        rms_absolute_radiance,
        max_relative,
        rms_relative: (sum_relative_squared / compared_words as f64).sqrt() as f32,
        max_luminance_absolute,
        rms_luminance_absolute,
        rms_luminance_relative: (sum_luminance_relative_squared / compared_cases as f64).sqrt()
            as f32,
        reference_rms_radiance,
        reference_rms_luminance,
        normalized_rms_absolute_radiance: rms_absolute_radiance / reference_rms_radiance,
        normalized_rms_luminance_absolute: rms_luminance_absolute / reference_rms_luminance,
    })
}

pub fn specular_coefficients_sha256(coefficients: &SheSpecularCoefficients) -> String {
    let bytes = coefficients
        .0
        .iter()
        .flat_map(|coefficient| coefficient.to_array())
        .flat_map(f32::to_le_bytes)
        .collect::<Vec<_>>();
    format!("{:x}", Sha256::digest(bytes))
}

pub fn specular_coefficients_bytes(coefficients: &SheSpecularCoefficients) -> Vec<u8> {
    coefficients
        .0
        .iter()
        .flat_map(|coefficient| coefficient.to_array())
        .flat_map(f32::to_le_bytes)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::{
        SIMSAT_RADIANCE_SHA256, SimSatSkyRadiance, radical_inverse_vdc,
        specular_coefficients_sha256,
    };
    use sha2::{Digest, Sha256};

    #[test]
    fn physical_radiance_asset_is_finite_positive_and_pinned() {
        let source = SimSatSkyRadiance::sealed_t300().unwrap();
        assert!(source.evaluate(bevy::math::Vec3::Z).min_element() > 0.0);
        assert_eq!(
            format!("{:x}", Sha256::digest(super::SIMSAT_RADIANCE_ASSET)),
            SIMSAT_RADIANCE_SHA256
        );
    }

    #[test]
    fn radical_inverse_preserves_upstream_bit_permutation() {
        assert_eq!(radical_inverse_vdc(0).to_bits(), 0.0_f32.to_bits());
        assert_eq!(radical_inverse_vdc(1).to_bits(), 0.5_f32.to_bits());
        assert_eq!(radical_inverse_vdc(2).to_bits(), 0.25_f32.to_bits());
    }

    #[test]
    fn coefficient_hash_rejects_one_word_corruption() {
        let mut coefficients = crate::she::SheSpecularCoefficients([bevy::math::Vec3::ZERO; 33]);
        let before = specular_coefficients_sha256(&coefficients);
        coefficients.0[17].y = f32::from_bits(1);
        assert_ne!(before, specular_coefficients_sha256(&coefficients));
    }
}
